/* VOLTA · Zeus: mascota propia y coach de Volta (sustituye al león).
   - 5 expresiones renderizadas en 3D (Three.js) a partir de un modelo hecho a mano: .claude/skills/volta-atleta-3d/zeus/zeus.html
   - Mensaje diario en Inicio según cómo te va (entrenaste hoy, llevas días sin entrenar, récord, objetivo cumplido…)
   - Tono a elegir: automático, épico, amigo o exigente
   - Botón flotante para hablar con Zeus desde cualquier pestaña
   - Plan gratis: 1 mensaje con IA al día (sin límite con Volta Pro) */
(function () {
  'use strict';
  if (typeof S === 'undefined' || typeof V === 'undefined') return;
  const IMG = {"feliz": "data:image/webp;base64,", "anima": "data:image/webp;base64,", "piensa": "data:image/webp;base64,", "preocupado": "data:image/webp;base64,", "guino": "data:image/webp;base64,"};
  window.ZEUS_IMG = IMG;
  { const st = document.createElement('style'); st.textContent = `.lion{background-image:url(${IMG.feliz})!important;background-size:contain!important;aspect-ratio:1;width:auto!important}`; document.head.appendChild(st); }
  const LI = { es: 0, en: 1, fr: 2, pt: 3, de: 1, it: 1, ru: 1, ar: 1, tr: 1, ja: 1, ko: 1, zh: 1, hi: 1 };
  const tr = (a) => (Array.isArray(a) ? a[LI[S.lang] || 0] || a[1] || a[0] : a);
  const T = {
    talk: ['Hablar con Zeus', 'Talk to Zeus', 'Parler à Zeus', 'Falar com Zeus'],
    coach: ['Zeus, tu coach', 'Zeus, your coach', 'Zeus, ton coach', 'Zeus, o teu coach'],
    tone: ['Tono de Zeus', 'Zeus’s tone', 'Ton de Zeus', 'Tom do Zeus'],
    tones: { auto: ['Automático', 'Automatic', 'Automatique', 'Automático'], epico: ['Épico', 'Epic', 'Épique', 'Épico'], amigo: ['Amigo', 'Friend', 'Ami', 'Amigo'], exigente: ['Exigente', 'Tough', 'Exigeant', 'Exigente'] },
    autoNote: ['En automático, Zeus elige el tono según cómo te va.', 'On automatic, Zeus picks the tone based on how you’re doing.', 'En automatique, Zeus choisit le ton selon ta progression.', 'No automático, o Zeus escolhe o tom segundo como te corre.'],
    quota: ['Has usado tu mensaje con IA de hoy. Mañana tienes otro; con Volta Pro, sin límite. Mientras, te respondo con mis consejos de siempre.', 'You’ve used today’s AI message. You get another tomorrow; with Volta Pro, unlimited. Meanwhile, here’s my usual advice.', 'Tu as utilisé ton message IA du jour. Tu en auras un autre demain ; avec Volta Pro, sans limite. En attendant, voici mes conseils habituels.', 'Já usaste a tua mensagem com IA de hoje. Amanhã tens outra; com o Volta Pro, sem limite. Entretanto, respondo com os meus conselhos de sempre.'],
    left: ['Mensajes con IA hoy', 'AI messages today', 'Messages IA aujourd’hui', 'Mensagens com IA hoje'],
    says: ['Zeus dice', 'Zeus says', 'Zeus dit', 'Zeus diz'],
  };
  // Mensajes: [situación][tono] → variantes en 4 idiomas. {n} = nombre
  const MSG = {
    today: {
      epico: [['{n}, el Olimpo te espera. Hoy se forja otra parte de tu leyenda.', '{n}, Olympus awaits. Today you forge another part of your legend.', '{n}, l’Olympe t’attend. Aujourd’hui tu forges ta légende.', '{n}, o Olimpo espera-te. Hoje forjas mais uma parte da tua lenda.'], ['Hasta los dioses entrenan, {n}. Tu rayo está cargado: úsalo.', 'Even gods train, {n}. Your bolt is charged: use it.', 'Même les dieux s’entraînent, {n}. Ton éclair est chargé : sers-t’en.', 'Até os deuses treinam, {n}. O teu raio está carregado: usa-o.']],
      amigo: [['¡Buenas, {n}! Hoy toca moverse un poco. Vamos juntos, ¿te apuntas?', 'Hey {n}! Time to move a bit today. Let’s do it together?', 'Salut {n} ! Aujourd’hui on bouge un peu. On y va ensemble ?', 'Olá, {n}! Hoje é dia de mexer. Vamos juntos?'], ['Aunque sea un entreno corto, {n}, cuenta muchísimo. Yo te acompaño.', 'Even a short workout counts a lot, {n}. I’ve got you.', 'Même une courte séance compte beaucoup, {n}. Je suis avec toi.', 'Mesmo um treino curto conta muito, {n}. Eu acompanho-te.']],
      exigente: [['{n}, sin excusas. Tu objetivo no se cumple solo. A entrenar.', '{n}, no excuses. Your goal won’t hit itself. Go train.', '{n}, pas d’excuses. Ton objectif ne se réalisera pas tout seul. Au boulot.', '{n}, sem desculpas. O teu objetivo não se cumpre sozinho. A treinar.'], ['La motivación va y viene, {n}. La disciplina se queda. Hoy cumples.', 'Motivation comes and goes, {n}. Discipline stays. Today you deliver.', 'La motivation va et vient, {n}. La discipline reste. Aujourd’hui tu assures.', 'A motivação vai e vem, {n}. A disciplina fica. Hoje cumpres.']],
    },
    done: {
      epico: [['¡Trueno y gloria, {n}! Entreno de hoy completado. Los dioses toman nota.', 'Thunder and glory, {n}! Today’s workout done. The gods take note.', 'Tonnerre et gloire, {n} ! Séance du jour terminée. Les dieux en prennent note.', 'Trovão e glória, {n}! Treino de hoje feito. Os deuses tomam nota.']],
      amigo: [['¡Bien hecho, {n}! Ahora a comer bien, beber agua y descansar. Te lo has ganado.', 'Well done, {n}! Now eat well, drink water and rest. You earned it.', 'Bien joué, {n} ! Maintenant mange bien, bois de l’eau et repose-toi.', 'Muito bem, {n}! Agora come bem, bebe água e descansa. Mereceste.']],
      exigente: [['Hecho. Mañana, un poco más, {n}. Así se construye un cuerpo.', 'Done. Tomorrow, a little more, {n}. That’s how a body is built.', 'C’est fait. Demain, un peu plus, {n}. C’est comme ça qu’on construit un corps.', 'Feito. Amanhã, um pouco mais, {n}. É assim que se constrói um corpo.']],
    },
    back: {
      epico: [['{n}, hasta Hércules tuvo días difíciles. Vuelve hoy y retoma tu camino al Olimpo.', '{n}, even Hercules had hard days. Come back today and resume your path to Olympus.', '{n}, même Hercule a eu des jours difficiles. Reviens aujourd’hui.', '{n}, até Hércules teve dias difíceis. Volta hoje e retoma o caminho.']],
      amigo: [['Te echaba de menos, {n}. No pasa nada por parar unos días: hoy con 20 minutos basta.', 'I missed you, {n}. A few days off is fine: 20 minutes today is enough.', 'Tu m’as manqué, {n}. Quelques jours de pause, ce n’est rien : 20 minutes suffisent aujourd’hui.', 'Tive saudades, {n}. Não faz mal parar uns dias: hoje bastam 20 minutos.']],
      exigente: [['{n}, llevas días sin entrenar. Hoy se acaba. Un entreno, ahora.', '{n}, it’s been days without training. That ends today. One workout, now.', '{n}, ça fait des jours sans t’entraîner. Ça s’arrête aujourd’hui.', '{n}, há dias que não treinas. Hoje acaba. Um treino, agora.']],
    },
    goal: {
      epico: [['¡Objetivo de la semana cumplido, {n}! Tu racha semanal multiplica tus Voltios.', 'Weekly goal done, {n}! Your weekly streak multiplies your Volts.', 'Objectif de la semaine atteint, {n} ! Ta série hebdo multiplie tes Volts.', 'Objetivo da semana cumprido, {n}! A tua sequência multiplica os teus Volts.']],
      amigo: [['¡Semana cumplida, {n}! Qué orgullo. Disfruta del descanso, que también es entrenar.', 'Week done, {n}! So proud. Enjoy the rest, it’s training too.', 'Semaine réussie, {n} ! Quelle fierté. Profite du repos, ça compte aussi.', 'Semana cumprida, {n}! Que orgulho. Aproveita o descanso, também é treinar.']],
      exigente: [['Semana cumplida, {n}. Bien. La que viene, igual o mejor.', 'Week done, {n}. Good. Next one, same or better.', 'Semaine réussie, {n}. Bien. La prochaine, pareille ou mieux.', 'Semana cumprida, {n}. Bem. A próxima, igual ou melhor.']],
    },
    pr: {
      epico: [['¡Récord personal, {n}! Has superado a tu yo de ayer. Eso es poder divino.', 'Personal record, {n}! You beat yesterday’s you. That’s divine power.', 'Record personnel, {n} ! Tu as battu ton toi d’hier. Pouvoir divin.', 'Recorde pessoal, {n}! Superaste o teu eu de ontem. Poder divino.']],
      amigo: [['¡Nuevo récord, {n}! Lo sabía. Sigue así, sin prisa pero sin pausa.', 'New record, {n}! I knew it. Keep going, steady and strong.', 'Nouveau record, {n} ! Je le savais. Continue comme ça.', 'Novo recorde, {n}! Eu sabia. Continua assim.']],
      exigente: [['Récord batido, {n}. Ahora a consolidarlo con buena técnica.', 'Record beaten, {n}. Now lock it in with good form.', 'Record battu, {n}. Maintenant consolide-le avec une bonne technique.', 'Recorde batido, {n}. Agora consolida com boa técnica.']],
    },
  };
  const MOOD = { today: 'feliz', done: 'anima', back: 'preocupado', goal: 'guino', pr: 'guino' };
  const img = (mood, size, cls) => `<img class="vx-zeus-img${cls ? ' ' + cls : ''}" src="${IMG[mood] || IMG.feliz}" width="${size}" height="${size}" alt="" aria-hidden="true">`;
  window.vxZeus = img;

  // ── Situación del día ──
  function situation() {
    const L = (Array.isArray(S.log) ? S.log : []).filter((l) => l && typeof l.t === 'number');
    const td = lk(Date.now());
    let pr = false;
    try { const v = window.vxVolt && window.vxVolt(); if (v) { const recent = v.entries.filter((e) => e.kind === 'train' && Date.now() - e.t < 2 * 864e5); pr = recent.some((e) => / récord| record| recorde/i.test(e.label)); if (v.weekDone >= v.goal && v.weekDone > 0 && !L.some((l) => lk(l.t) === td)) return { k: 'goal', v }; } } catch (e) { /* sin Voltios */ }
    if (L.some((l) => lk(l.t) === td)) return { k: pr ? 'pr' : 'done' };
    const last = L.reduce((m, l) => Math.max(m, l.t), 0);
    if (last && Date.now() - last > 3 * 864e5) return { k: 'back' };
    return { k: 'today' };
  }
  const toneOf = (k) => {
    const t = S.zeusTone || 'auto';
    if (t !== 'auto') return t;
    if (k === 'back') return 'amigo';
    if (k === 'today') { try { const v = window.vxVolt(); const dow = (new Date().getDay() + 6) % 7; if (dow >= 3 && v.weekDone < v.goal) return 'exigente'; } catch (e) { /* por defecto */ } return 'epico'; }
    return 'epico';
  };
  function message() {
    const s = situation(), tone = toneOf(s.k), list = MSG[s.k][tone];
    const pick = list[Math.floor(Date.now() / 864e5) % list.length];
    const name = (S.userProfile && S.userProfile.name) || '';
    const txt = tr(pick).replace('{n}, ', name ? name + ', ' : '').replace(', {n}', name ? ', ' + name : '').replace('{n}', name);
    return { mood: MOOD[s.k], txt: txt.charAt(0).toUpperCase() + txt.slice(1), tone, k: s.k };
  }
  window.vxZeusMessage = message;
  function zeusCard() {
    const m = message();
    return `<div class="card vx-zeus-card" onclick="go('coach')" role="button" tabindex="0" aria-label="${tr(T.talk)}">${img(m.mood, 76)}<div class="g"><div class="mu" style="font-size:12px">⚡ ${tr(T.says)}</div><div class="vx-zeus-say">${esc(m.txt)}</div><div class="vx-zeus-cta">${tr(T.talk)} ›</div></div></div>`;
  }
  window.vxZeusCard = zeusCard;

  // ── Tono y límite de IA ──
  window.vxZeusTone = (t) => { S.zeusTone = t; try { sv(); } catch (e) { /* sin guardar */ } R(); };
  window.vxZeusTonePrompt = () => {
    const t = toneOf(situation().k);
    const P = { epico: ' Hablas como Zeus, rey del Olimpo: épico, enérgico y motivador, con guiños a la mitología griega, pero claro y práctico.', amigo: ' Hablas como Zeus en plan amigo cercano: cálido, comprensivo y animando sin presionar.', exigente: ' Hablas como Zeus en plan entrenador exigente: directo, sin excusas, firme pero respetuoso y nunca ofensivo.' };
    const LN = { es: 'español', en: 'inglés', fr: 'francés', pt: 'portugués', de: 'alemán', it: 'italiano', ru: 'ruso', ar: 'árabe', tr: 'turco', ja: 'japonés', ko: 'coreano', zh: 'chino simplificado', hi: 'hindi' };
    return P[t] + ' Responde siempre en ' + (LN[S.lang] || 'el idioma del usuario') + '. Nunca uses insultos ni palabrotas.';
  };
  const FREE = 1;
  window.vxZeusQuota = () => {
    if (S.pro) return true;
    const d = lk(Date.now()); if (!S.zeusAI || S.zeusAI.d !== d) S.zeusAI = { d, n: 0 };
    if (S.zeusAI.n >= FREE) return false;
    S.zeusAI.n++; try { sv(); } catch (e) { /* sin guardar */ } return true;
  };
  window.vxZeusQuotaMsg = () => tr(T.quota);
  const quotaLeft = () => { if (S.pro) return '∞'; const d = lk(Date.now()); const n = S.zeusAI && S.zeusAI.d === d ? S.zeusAI.n : 0; return Math.max(0, FREE - n) + '/' + FREE; };

  // ── Inserciones ──
  if (typeof V.home === 'function') {
    const _home = V.home;
    V.home = function () {
      let h = _home.apply(this, arguments);
      try {
        h = h.replace(/<div class="vx-quote">[\s\S]*?<\/p><\/div>/, '');
        const card = zeusCard(), i = h.indexOf('<div class="card vx-streak');
        h = i !== -1 ? h.slice(0, i) + card + h.slice(i) : h + card;
      } catch (e) { /* Inicio original */ }
      return h;
    };
  }
  if (typeof V.coach === 'function') {
    const _coach = V.coach;
    V.coach = function () {
      let h = _coach.apply(this, arguments);
      try {
        const cur = S.zeusTone || 'auto';
        const chips = `<div class="card vx-zeus-tone"><div class="row sp"><b>${tr(T.tone)}</b><span class="mu" style="font-size:12px">${tr(T.left)}: ${quotaLeft()}</span></div><div class="chips" role="radiogroup" aria-label="${tr(T.tone)}">${['auto', 'epico', 'amigo', 'exigente'].map((k) => `<div class="chip ${cur === k ? 'on' : ''}" role="radio" aria-checked="${cur === k}" onclick="vxZeusTone('${k}')">${tr(T.tones[k])}</div>`).join('')}</div>${cur === 'auto' ? `<div class="mu" style="font-size:12px">${tr(T.autoNote)}</div>` : ''}</div>`;
        const m = message();
        h = h.replace(/<div class="card row"><i class="lion"[^>]*><\/i><div class="mu g"[^>]*>[^<]*<\/div><\/div>/, `<div class="card row vx-zeus-head">${img(m.mood, 72)}<div class="g"><b>${tr(T.coach)}</b><div class="mu">${esc(m.txt)}</div></div></div>` + chips);
      } catch (e) { /* coach original */ }
      return h;
    };
  }
  // Botón flotante (en las pestañas principales; no durante el entreno ni en el chat)
  const fab = document.createElement('button');
  fab.type = 'button'; fab.className = 'vx-zeus-fab'; fab.setAttribute('aria-label', tr(T.talk)); fab.innerHTML = img('feliz', 58);
  fab.addEventListener('click', () => { try { go('coach'); } catch (e) { /* sin navegación */ } });
  document.body.appendChild(fab);
  const showFab = () => { try { const top = S.stack && S.stack.length ? S.stack[S.stack.length - 1] : ''; const ok = S.onboarded && !top && S.obi == null && !S.obEdit && !document.querySelector('.vm,#ob'); fab.hidden = !ok; fab.setAttribute('aria-label', tr(T.talk)); } catch (e) { fab.hidden = true; } };
  const _R = R;
  R = function () { _R.apply(this, arguments); showFab(); };
  showFab();

  if (window.vxAddTr) window.vxAddTr(`
¡Soy Zeus!|I’m Zeus!|Je suis Zeus !|Sou o Zeus!
Zeus, tu coach IA|Zeus, your AI coach|Zeus, ton coach IA|Zeus, o teu coach IA
Zeus · tu coach|Zeus · your coach|Zeus · ton coach|Zeus · o teu coach
Zeus está pensando…|Zeus is thinking…|Zeus réfléchit…|O Zeus está a pensar…
Pregúntale a Zeus lo que quieras: técnica, carga, dolor, comida o motivación|Ask Zeus anything: technique, load, pain, food or motivation|Demande à Zeus ce que tu veux : technique, charge, douleur, nutrition ou motivation|Pergunta ao Zeus o que quiseres: técnica, carga, dor, comida ou motivação
`);
})();
